vector<int> mergeSortedArrays(const vector<int>& arr1, const vector<int>& arr2) {
    vector<int> result;
    size_t i = 0, j = 0;

    while (i < arr1.size() && j < arr2.size()) {
        if (arr1[i] <= arr2[j]) {
            result.push_back(arr1[i]);
            ++i;
        } else {
            result.push_back(arr2[j]);
            ++j;
        }
    }

    // Add the remaining elements from either array
    while (i < arr1.size()) {
        result.push_back(arr1[i]);
        ++i;
    }

    while (j < arr2.size()) {
        result.push_back(arr2[j]);
        ++j;
    }

    return result;
}
